async fn take_feedback(&self, pr: &PrRef, author: &AuthorId) -> Result<()> {
    // Commands of the author that have no answer comment yet.
    for command in self.scm.feedback_commands(pr, author).await? {
        self.scm.answer_feedback(pr, &command, "Recorded.").await?;
        let request = command.request.clone().map_err(Error::Invalid)?;
        let key = command.session.clone().ok_or(Error::Invalid("no results".into()))?;
        self.app
            .give_feedback(Some(author), &key, &request, Some(&command.source))
            .await?;
    }
    Ok(())
}

