fn swap(&self, key: &str, expected: &str, new: &str) -> io::Result<bool> {
    // lock() opens <dir>/.lock and takes an exclusive advisory
    // lock on it; the lock lasts as long as the returned File lives.
    let _ = self.lock()?;
    let stored = self.read(key)?;
    if stored != expected {
        return Ok(false);
    }
    self.write(key, new)?;
    Ok(true)
}

